ALTER TABLE discount_codes ADD COLUMN archived_at timestamptz;
ALTER TABLE discount_codes ADD CONSTRAINT archived_coupon_disabled CHECK (archived_at IS NULL OR NOT enabled);

INSERT INTO blog_posts (slug,title,description,category,body,seo_title,seo_description,cover_image,cover_alt,cover_width,cover_height,state,published_at) VALUES ('clothing-combinations-game','بازی ترکیب لباس‌ها؛ چند انتخاب متفاوت می‌توان ساخت؟','با پیراهن و شلوارهای کاغذی ترکیب‌های متفاوت بسازید و با یک جدول ساده انتخاب‌های تکراری و جاافتاده را پیدا کنید.','بازی در خانه','دو پیراهن و سه شلوار کاغذی روی میز بگذارید. هر پیراهن را با کدام شلوار می‌توان پوشید؟ این پرسش شروع یک بازی مشترک است: کودک انتخاب می‌کند، شما انتخابش را ثبت می‌کنید و بعد با هم دنبال ترکیب تازه می‌گردید. لازم نیست از ابتدا فرمول یا پاسخ نهایی را بگویید.

## وسایل و شروع بازی

دو پیراهن کاغذی در رنگ‌های متفاوت و سه شلوار با رنگ‌های مشخص آماده کنید. قطعه‌ها را بزرگ ببرید تا جابه‌جایی آن‌ها آسان باشد. برای شروع فقط یک پیراهن و دو شلوار بدهید. از کودک بخواهید یک لباس کامل بسازد و دربارهٔ انتخابش حرف بزند. اگر نوشتن دشوار است، ترکیب‌ها را نقاشی کنید.

## هر بار یک انتخاب را ثابت نگه دارید

پیراهن اول را نگه دارید و شلوارها را یکی‌یکی کنار آن بگذارید. هر ترکیب را ثبت کنید. سپس پیراهن را عوض کنید و همان کار را تکرار کنید. بپرسید: «این لباس را قبلاً ساخته بودیم؟» فرصت بدهید کودک خودش به ثبت‌های قبلی نگاه کند.

جدولی با دو ردیف و سه ستون بکشید. پیراهن‌ها کنار ردیف‌ها و شلوارها بالای ستون‌ها باشند. هر خانه جای یک ترکیب است. جدول را همراه کودک پر کنید؛ خانهٔ خالی می‌تواند سرنخی برای انتخاب بعدی باشد. با این دو پیراهن و سه شلوار، شش ترکیب متفاوت داریم.

## تعداد ترکیب‌ها و تعداد قطعه‌ها

اگر کودک گفت پنج لباس داریم، از او بخواهید منظورش را نشان دهد. شاید پنج قطعه را شمرده باشد. توضیح دهید که این بار هر پیراهن و شلوار با هم یک انتخاب می‌سازند. یک ترکیب بسازید و بپرسید آیا می‌توان با همین پیراهن انتخاب دیگری ساخت.

## قانون تازه بسازید

جای شما و کودک عوض شود: او رنگ‌ها را انتخاب کند و شما ترکیب بسازید. بعد قانونی اضافه کنید؛ مثلاً پیراهن آبی کنار شلوار آبی قرار نگیرد. ترکیب‌های مجاز را بررسی کنید. هر بار فقط یک قانون را عوض کنید تا دلیل حذف یک انتخاب روشن بماند.

اگر بازی طولانی شد، همان دو انتخاب نخست کافی است. هدف، گفت‌وگو دربارهٔ انتخاب‌ها و ثبت منظم آن‌هاست. برای ادامهٔ دیجیتال، توضیحات [سرزمین ترکیب‌ها](/special-products/combination-land) را ببینید. برای فعالیتی دیگر، [بازی الگویابی با شکل و رنگ](/blog/shape-and-colour-pattern-games) را امتحان کنید.','بازی ترکیب لباس‌ها؛ چند انتخاب متفاوت می‌توان ساخت؟','با پیراهن و شلوارهای کاغذی ترکیب‌های متفاوت بسازید و با یک جدول ساده انتخاب‌های تکراری و جاافتاده را پیدا کنید.','/blog-covers/clothing-combinations-game.webp','مادر و کودک در حال ساخت ترکیب‌های لباس با قطعه‌های کاغذی',1536,1024,'PUBLISHED',now()) ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_posts (slug,title,description,category,body,seo_title,seo_description,cover_image,cover_alt,cover_width,cover_height,state,published_at) VALUES ('mystery-bag-shape-game','کیسهٔ شگفتی؛ بازی شناخت شکل‌ها با لمس و توصیف','با چند شکل بزرگ و یک کیسهٔ پارچه‌ای بازی نوبتی بسازید؛ شکل را لمس کنید، ویژگی‌های آن را توصیف کنید و حدس را با مشاهده بررسی کنید.','بازی در خانه','یک شکل بزرگ در کیسه بگذارید و بدون نگاه کردن لمسش کنید. گوشه دارد؟ کناره‌هایش صاف‌اند یا خمیده؟ بازی کیسهٔ شگفتی فرصتی برای توصیف چیزهایی است که کودک احساس می‌کند. پیدا کردن نام شکل تنها بخش بازی نیست؛ شنیدن دلیل یک حدس هم ارزش دارد.

## کیسه را آماده کنید

کیسهٔ پارچه‌ای تمیز و چند قطعهٔ بزرگ، سالم و بدون لبهٔ تیز انتخاب کنید. قطعه‌ها نباید آن‌قدر کوچک باشند که خطر بلع داشته باشند. ابتدا همه را روی میز بگذارید تا کودک ببیند و لمس کند. با دو شکل متفاوت، مثلاً دایره و مثلث، شروع کنید. اگر دست بردن در کیسه خوشایند نیست، شکل را زیر پارچه بگذارید یا اجازه دهید بازی با نگاه انجام شود.

## توصیف پیش از نام بردن

نوبت اول با شما باشد. شکلی را لمس کنید و با جمله‌های کوتاه توضیح دهید: «کنارهٔ صاف پیدا کردم؛ اینجا هم یک گوشه است.» سپس شکل را بیرون بیاورید و آنچه گفته‌اید نشان دهید. کودک می‌تواند شکل بعدی را انتخاب کند، ویژگی‌اش را بگوید یا با اشاره نشان دهد. نیازی نیست اصطلاح‌ها را کامل به زبان بیاورد.

## حدس را بررسی کنید

اگر حدس متفاوت بود، شکل را بیرون بیاورید و کنار نمونه‌های روی میز بگذارید. بپرسید: «کدام بخش باعث شد این حدس را بزنی؟» با هم کناره‌ها و گوشه‌ها را لمس کنید. بازی را به مسابقهٔ سرعت تبدیل نکنید؛ فرصت بررسی دوباره از درست گفتن فوری نام شکل مهم‌تر است.

## یک ویژگی را تغییر دهید

وقتی دو شکل آشنا شدند، شکل سوم را اضافه کنید. بعد دو مربع با اندازه‌های متفاوت انتخاب کنید. دربارهٔ چیزهایی که تغییر کرده و چیزهایی که همان مانده حرف بزنید. اگر رنگ‌ها متفاوت‌اند، یادآوری کنید که در کیسه رنگ را نمی‌بینیم؛ پس باید از نشانهٔ دیگری کمک بگیریم.

## نوبت راهنمایی کودک

این بار کودک شکلی پنهان کند و شما با پرسش‌های کوتاه حدس بزنید. مثلاً بپرسید: «گوشه دارد؟» اگر پاسخ روشن نبود، با هم بررسی کنید. در پایان، شکل‌های گوشه‌دار را یک طرف و شکل‌های با کنارهٔ خمیده را طرف دیگر بگذارید.

بازی را با علاقهٔ کودک کوتاه یا بلند کنید. برای ادامهٔ فعالیت‌های دسته‌بندی، [دسته‌ساز کوچک](/special-products/bundle-builder) را ببینید. پیشنهادهای [همراهی بدون گفتن جواب](/blog/helping-without-giving-the-answer) هم برای گفت‌وگوی بعدی ایده می‌دهد.','کیسهٔ شگفتی؛ بازی شناخت شکل‌ها با لمس و توصیف','با چند شکل بزرگ و یک کیسهٔ پارچه‌ای بازی نوبتی بسازید؛ شکل را لمس کنید، ویژگی‌های آن را توصیف کنید و حدس را با مشاهده بررسی کنید.','/blog-covers/mystery-bag-shape-game.webp','پدر و کودک در حال شناخت شکل‌های چوبی با کیسهٔ پارچه‌ای',1536,1024,'PUBLISHED',now()) ON CONFLICT (slug) DO NOTHING;
